// Category B — no headless component and no behavior; this is a decorative progress line.
import type { CSSProperties, Ref } from "react";
import "./ProgressConnector.css";

export interface ProgressConnectorProps {
  /** Whether the preceding segment is complete. */
  isComplete?: boolean;
  className?: string;
  style?: CSSProperties;
  /** Forwarded to the underlying <span> DOM node. */
  ref?: Ref<HTMLSpanElement>;
}

/**
 * A decorative connector between two nodes in a discrete sequence.
 *
 * The connector is always hidden from assistive technology. Consumers that need completion
 * announced must provide that information themselves in adjacent text.
 */
export function ProgressConnector({
  isComplete,
  className,
  style,
  ref,
}: ProgressConnectorProps) {
  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-complete={isComplete || undefined}
      className={className ? `sd-progress-connector ${className}` : "sd-progress-connector"}
      style={style}
    />
  );
}

.sd-progress-connector {
  /* `display` is load-bearing: a bare <span> is inline, and an inline non-replaced box ignores
     `height`, so the connector rendered as NOTHING on its own — caught by a coverage gap, confirmed
     by a blank screenshot. Inside a flex container a flex item is blockified anyway, so this is a
     no-op where the Blocks use it and the fix where anyone else does. */
  display: block;
  align-self: center;
  height: var(--sd-progress-connector-thickness);
  /* The same thickness on the other axis, for a consumer that runs its markers in a COLUMN: there
     the consumer's `flex-basis` sets the length and overrides `height`, and a centred item with no
     content would otherwise be zero wide. In a row it binds only when a track leaves less than one thickness for the rule. */
  min-width: var(--sd-progress-connector-thickness);
  background: var(--sd-progress-connector-background);
}

.sd-progress-connector[data-complete] {
  background: var(--sd-progress-connector-background-complete);
}
